void moon_textures_init(void) {
    static bool s_inited = false;   /* single task: the moonbase session holder */
    if (s_inited) return;
    s_inited = true;

    for (int i = 0; i < 8192; i++) {
        uint8_t b = g_tex_regolith_4bit[i];
        g_tex_regolith[i * 2]     = g_tex_regolith_pal[(b >> 4) & 0x0F];
        g_tex_regolith[i * 2 + 1] = g_tex_regolith_pal[b & 0x0F];
    }
}

